verifyQuery:
source: monthly is order_items -> {
  group_by: mo is created_at.month
  aggregate: sales is sale_price.sum()
}
run: monthly extend {
  join_one: prev is monthly on prev.mo = mo - 1 month
} -> {
  where: mo >= @2022-02-01 and mo < @2022-11-01
  select:
    drop_month is month(mo)
    month_sales is sales
    prev_month_sales is prev.sales
    mom_change is round(sales - prev.sales, 2)
    mom_pct is round(sales / prev.sales - 1, 4)
  order_by: mom_pct asc
  limit: 1
}
